def get_git_sha(detail_info=False):
    import subprocess

    def run_git_text(cmd):
        try:
            return subprocess.check_output(
                cmd,
                encoding="utf-8",
                errors="replace",
            ).rstrip()
        except Exception:
            return "unknown"

    cmd = ["git", "rev-parse", "--short", "HEAD"]
    sha = run_git_text(cmd)
    if not detail_info:
        return sha
